package org.mathhacks.multibind;

import java.nio.file.*;
import java.util.*;
import org.mathhacks.multibind.Model.Edge;
import org.mathhacks.multibind.Model.State;
import org.mathhacks.multibind.ThermodynamicRates.Rate;

/** No test framework at runtime. Independent author outputs are checked, not generated by Java. */
public final class CoreTest {
    private static int assertions;
    private static double maxScaledReferenceError;
    private static double maxWellConditionedReferenceError;
    private CoreTest() { }

    public static void main(String[] args) throws Exception {
        analyticCases();
        rateProjectionRegressions();
        rejectionCases();
        csvCases();
        int cases = referenceCases(Path.of(args.length == 0 ? "src/test/resources/upstream" : args[0]));
        System.out.printf(Locale.ROOT,
            "PASS: %d assertions; %d author reference cases; max reference error / max(1,|expected|) = %.3g%n",
            assertions, cases, maxScaledReferenceError);
        System.out.printf(Locale.ROOT, "Well-conditioned cases: max scaled reference error = %.3g%n",
                          maxWellConditionedReferenceError);
    }

    private static void analyticCases() {
        var model = new Model(List.of(new State("A"), new State("B")), List.of(Edge.energy("A", "B", 2, 0.3)));
        var fit = Multibind.fit(model);
        close(fit.energy(0), 0); close(fit.energy(1), 2);
        close(fit.centeredCovariance(0, 0), 0.075);
        close(fit.centeredCovariance(0, 1), -0.075);
        close(fit.referenceCovariance(0, 0), 0);
        close(fit.referenceCovariance(1, 1), 0.3);
        close(fit.differenceStandardError(0, 1), Math.sqrt(0.3));
        close(fit.probability(1), 1 / (1 + Math.exp(2)));
        close(fit.chiSquare(), 0); check(fit.degreesOfFreedom() == 0, "tree has no cycle constraint");

        var states = List.of(new State("A"), new State("B"), new State("C"));
        fit = Multibind.fit(new Model(states, List.of(Edge.energy("A", "B", 1, 1),
            Edge.energy("B", "C", 1, 1), Edge.energy("C", "A", -1, 1))));
        close(fit.energy(1), 2.0 / 3); close(fit.energy(2), 4.0 / 3);
        close(fit.chiSquare(), 1.0 / 3); check(fit.degreesOfFreedom() == 1, "one independent cycle");
        double closure = fit.energyDifference(0, 1) + fit.energyDifference(1, 2) + fit.energyDifference(2, 0);
        close(closure, 0);

        var uncertain = Multibind.fit(new Model(states, List.of(Edge.energy("A", "B", 1, 1),
            Edge.energy("B", "C", 1, 1), Edge.energy("C", "A", -1, 100))));
        close(uncertain.edgeResidual(2) / uncertain.edgeResidual(0), 100);

        var original = new Model(states, List.of(Edge.energy("A", "B", 2, 0.1),
            Edge.energy("B", "C", 3, 0.2), Edge.energy("C", "A", -4, 0.5)));
        var first = Multibind.fit(original);
        var reordered = Multibind.fit(new Model(List.of(states.get(2), states.get(0), states.get(1)), original.edges()));
        close(first.energyDifference(0, 1), reordered.energyDifference(1, 2));
        close(first.probability(0), reordered.probability(1));

        var single = Multibind.fit(new Model(List.of(new State("only")), List.of()));
        close(single.energy(0), 0); close(single.probability(0), 1); close(single.centeredCovariance(0, 0), 0);
        close(Multibind.protonationEnergy(7, 7), 0);
        close(Multibind.protonationEnergy(7, 8), Math.log(10));
        close(Multibind.bindingEnergy(-4, 0.1, 0.1), -4);
        close(Multibind.bindingEnergy(-4, 0.01, 0.1), -4 + Math.log(10));
        var nonstandard = Multibind.fit(new Model(List.of(new State("A"), new State("B")),
            List.of(new Edge("A", "B", -4, 1, "Na+", 0.1))), 7, Map.of("Na+", 0.1));
        close(nonstandard.energy(1), -4);

        var extreme = Multibind.fit(new Model(List.of(new State("A"), new State("B")),
            List.of(Edge.energy("A", "B", -1000, 1))));
        close(extreme.probability(0), 0); close(extreme.probability(1), 1);
        var categories = new Model(List.of(new State("A", Map.of("bound", "no")),
            new State("B", Map.of("bound", "yes"))), List.of(Edge.energy("A", "B", -1000, 1)));
        var grouped = Multibind.fit(categories);
        var macro = grouped.macrostateDifference("bound", "no", "yes");
        close(macro.energy(), -1000); close(macro.covarianceStandardError(), 1);
        close(macro.paperStandardError(), Math.sqrt(0.5));
        rejects(() -> grouped.macrostateDifference("bound", "missing", "yes"));

        var rates = ThermodynamicRates.fit(List.of(new Rate("A", "B", 2, 0.1), new Rate("B", "A", 1, 0.1),
            new Rate("B", "C", 3, 0.1), new Rate("C", "B", 1, 0.1),
            new Rate("C", "A", 0.2, 0.1), new Rate("A", "C", 1, 0.1)));
        close(Math.log(rates.rate(0, 1)) - Math.log(rates.rate(1, 0))
            + Math.log(rates.rate(1, 2)) - Math.log(rates.rate(2, 1))
            + Math.log(rates.rate(2, 0)) - Math.log(rates.rate(0, 2)), 0);
        var pair = ThermodynamicRates.project(40, 70, 20, 20, -1, 1, 1);
        double baseline = objective(40, 70, pair.forward(), pair.backward(), 20, 20);
        for (double scale : new double[]{0.5, 0.99, 1.01, 2})
            check(objective(40, 70, pair.forward() * scale, pair.backward() * scale, 20, 20) > baseline,
                  "projection minimizes the fixed-dG Gaussian objective");
        pair = ThermodynamicRates.project(1, 1, 1, 1, 700, 0.1, 0.1);
        check(pair.forward() > 0 && Double.isFinite(pair.backward()), "large delta projection stays finite");
        pair = ThermodynamicRates.project(1e300, 1e-300, 1, 1, 0, 0, 0);
        close(pair.forward() / 1e300, 0.5); close(pair.backward() / 1e300, 0.5);
    }

    private static double objective(double f, double b, double pf, double pb, double vf, double vb) {
        return Math.pow(pf - f, 2) / vf + Math.pow(pb - b, 2) / vb;
    }

    private static void rateProjectionRegressions() {
        // Author tests/rates/test_thermo_rates.py: seven independently published regression cases.
        double[][] cases = {
            {70,40,20,20,-1,1,1,21.30529001482594,57.91378269735128,34.74749438345482,125.0178900064783},
            {173.06,7000,100,70.71*70.71,-3.55,0.05030344,0.02511696,199.96262447,6961.36233140,10.73760592,541.23325915},
            {114.51,2300,22.36*22.36,31.62*31.62,-1.33,0.03988453,0.05030344,547.70256004,2070.88714299,27.43328993,168.62175184},
            {9562.58,5800,54.77*54.77,31.62*31.62,0.5,0.03988452590655562,0.03946882571557041,9562.581768123830,5799.999028376148,281.5180681407045,367.5227630083491},
            {197.84,120,100,3.57*3.57,0.65,0.02505446,0.03946883,219.66055596,114.67286556,6.67187784,6.39301847},
            {7359.76,300,31.62*31.62,7.07*7.07,3.23,0.02477145,0.02505446,7366.56254336,291.40278888,7.64476117,10.27138954},
            {7359.76,300,0,0,3.23,0.02477145,0.02505446,7360.11018080,291.14754956,0.39282607,10.25795585}
        };
        for (double[] c : cases) {
            var pair = ThermodynamicRates.project(c[1], c[0], c[3], c[2], c[4], c[6], c[5]);
            near(pair.backward(), c[7], 1e-5, 1e-8, "author pair backward");
            near(pair.forward(), c[8], 1e-5, 1e-8, "author pair forward");
            near(pair.backwardPaperStandardError(), c[9], 1e-5, 1e-8, "author pair backward error");
            near(pair.forwardPaperStandardError(), c[10], 1e-5, 1e-8, "author pair forward error");
        }
    }

    private static void rejectionCases() {
        var states = List.of(new State("A"), new State("B"));
        rejects(() -> new Model(List.of(), List.of()));
        rejects(() -> new Model(states, List.of()));
        rejects(() -> new Model(List.of(new State("A"), new State("A")), List.of()));
        rejects(() -> new Model(states, List.of(Edge.energy("A", "X", 1, 1))));
        rejects(() -> new Model(states, List.of(Edge.energy("A", "B", 1, 1), Edge.energy("B", "A", -1, 1))));
        rejects(() -> Edge.energy("A", "A", 0, 1));
        rejects(() -> Edge.energy("A", "B", 0, 0));
        rejects(() -> Edge.energy("A", "B", 0, -1));
        rejects(() -> Edge.energy("A", "B", Double.NaN, 1));
        rejects(() -> Multibind.fit(new Model(states, List.of(new Edge("A", "B", -1, 1, "Na+", 1)))));
        rejects(() -> Multibind.bindingEnergy(1, 0, 1));
        rejects(() -> Multibind.bindingEnergy(1, -1, 1));
        rejects(() -> Multibind.protonationEnergy(7, Double.NaN));
        rejects(() -> ThermodynamicRates.fit(List.of(new Rate("A", "B", 1, 1))));
        rejects(() -> ThermodynamicRates.fit(List.of(new Rate("A", "B", 1, 0), new Rate("B", "A", 1, 0))));
        rejects(() -> ThermodynamicRates.fit(List.of(new Rate("A", "B", 1, 1), new Rate("A", "B", 1, 1))));
        rejects(() -> new Rate("A", "B", 0, 1));
        rejects(() -> new Rate("A", "B", 1, -1));
        rejects(() -> ThermodynamicRates.project(1, 1, 1, 1, Double.POSITIVE_INFINITY, 0, 0));
        rejects(() -> ThermodynamicRates.project(1, 1, 1, 1, 1000, 0, 0));
    }

    private static void csvCases() throws Exception {
        Path dir = Files.createTempDirectory("multibind-csv-");
        try {
            Path states = dir.resolve("states.csv"), graph = dir.resolve("graph.csv");
            Files.writeString(states, "# comment\nname,group\n\"A,1\",a\n\"B\"\"2\",b\n");
            Files.writeString(graph, "state1,state2,value,variance,ligand,standard_state\n\"A,1\",\"B\"\"2\",2,1,helm,1\n");
            var model = ModelCsv.read(states, graph);
            check(model.states().get(0).name().equals("A,1"), "quoted comma preserved");
            check(model.states().get(1).name().equals("B\"2"), "escaped quote preserved");
            close(Multibind.fit(model).energy(1), 2);
            Files.writeString(graph, "x,x\n1,2\n");
            rejectsChecked(() -> ModelCsv.rows(graph));
            Files.writeString(graph, "x,y\n\"broken,2\n");
            rejectsChecked(() -> ModelCsv.rows(graph));
            Files.writeString(graph, "x,y\n1,2,3\n");
            rejectsChecked(() -> ModelCsv.rows(graph));
        } finally {
            try (var files = Files.list(dir)) { for (Path file : files.toList()) Files.delete(file); }
            Files.delete(dir);
        }
    }

    private static int referenceCases(Path root) throws Exception {
        int count = 0;
        for (var row : ModelCsv.rows(root.resolve("cases.csv"))) {
            // This author's regression spans rates 1e-2..1e10 and has condition ~2.5e9.
            // Use its upstream regression tolerance, rather than the tight tolerance of well-conditioned examples.
            boolean illConditioned = row.get("id").equals("author-nine-state");
            Path dir = root.resolve(row.get("id"));
            ThermodynamicRates.RateFit rateFit = null;
            Multibind.Fit fit;
            if (row.get("kind").equals("rates")) {
                rateFit = ThermodynamicRates.fit(ModelCsv.readRates(dir.resolve("rates.csv")));
                fit = rateFit.potential();
            } else {
                Map<String, Double> concentrations = new HashMap<>();
                for (String ligand : List.of("Na+", "Zn"))
                    if (!row.getOrDefault(ligand, "").isBlank())
                        concentrations.put(ligand, Double.parseDouble(row.get(ligand)));
                fit = Multibind.fit(ModelCsv.read(dir.resolve("states.csv"), dir.resolve("graph.csv")),
                                    Double.parseDouble(row.get("pH")), concentrations);
            }
            List<Multibind.MacrostateDifference> macros = new ArrayList<>();
            if (Files.readAllLines(dir.resolve("macros.csv")).size() > 1)
                for (var macro : ModelCsv.rows(dir.resolve("macros.csv")))
                    macros.add(fit.macrostateDifference(macro.get("category"), macro.get("source"), macro.get("destination")));
            for (var expected : ModelCsv.rows(dir.resolve("expected.csv"))) {
                int i = Integer.parseInt(expected.get("i")), j = Integer.parseInt(expected.get("j"));
                double wanted = Double.parseDouble(expected.get("value"));
                double actual = switch (expected.get("quantity")) {
                    case "energy" -> fit.energy(i);
                    case "probability" -> fit.probability(i);
                    case "state_error" -> fit.paperStateStandardError(i);
                    case "covariance" -> fit.centeredCovariance(i, j);
                    case "difference" -> fit.energyDifference(i, j);
                    case "rate" -> Objects.requireNonNull(rateFit).rate(i, j);
                    case "rate_error" -> Objects.requireNonNull(rateFit).paperStandardError(i, j);
                    case "macro_energy" -> macros.get(i).energy();
                    case "macro_error" -> macros.get(i).paperStandardError();
                    default -> throw new AssertionError("Unknown reference quantity " + expected);
                };
                near(actual, wanted, illConditioned ? 1e-5 : 2e-8, illConditioned ? 1e-6 : 2e-10,
                     row.get("id") + " " + expected);
                maxScaledReferenceError = Math.max(maxScaledReferenceError, Math.abs(actual - wanted) / Math.max(1, Math.abs(wanted)));
                if (!illConditioned) maxWellConditionedReferenceError = Math.max(maxWellConditionedReferenceError,
                    Math.abs(actual - wanted) / Math.max(1, Math.abs(wanted)));
            }
            double sum = 0;
            if (illConditioned) {
                // Independent closed-form weighted projection for this single oriented ring.
                double closure = 0, totalVariance = 0, energy = 0;
                for (int e = 0; e < fit.model().edges().size(); e++) {
                    closure += fit.inputDelta(e); totalVariance += fit.inputVariance(e);
                }
                for (int e = 0; e < fit.size() - 1; e++) {
                    energy += fit.inputDelta(e) - closure * fit.inputVariance(e) / totalVariance;
                    near(fit.energy(e + 1), energy, 1e-10, 1e-9, "ill-conditioned ring closed-form solution");
                }
            }
            for (int i = 0; i < fit.size(); i++) {
                sum += fit.probability(i);
                check(fit.probability(i) >= 0, "nonnegative probability");
                double covarianceSum = 0;
                for (int j = 0; j < fit.size(); j++) {
                    covarianceSum += fit.centeredCovariance(i, j);
                    close(fit.centeredCovariance(i, j), fit.centeredCovariance(j, i));
                    if (rateFit != null && rateFit.rate(i, j) > 0) {
                        close(Math.log(rateFit.rate(j, i)) - Math.log(rateFit.rate(i, j)), fit.energyDifference(i, j));
                        near(rateFit.rate(i, j) * fit.probability(i), rateFit.rate(j, i) * fit.probability(j),
                             1e-9, 1e-12, "equilibrium detailed balance");
                    }
                }
                near(covarianceSum, 0, 0, illConditioned ? 1e-6 : 1e-8, "centered covariance row sum");
            }
            close(sum, 1);
            System.out.println("  PASS " + row.get("id"));
            count++;
        }
        Path rejected = root.resolve("rejected-yiip-site-b");
        rejectsChecked(() -> ModelCsv.read(rejected.resolve("states.csv"), rejected.resolve("graph.csv")));
        System.out.println("  PASS rejected-yiip-site-b (incomplete upstream state list)");
        return count;
    }

    private static void close(double actual, double expected) { near(actual, expected, 1e-9, 1e-10, "analytic/invariant"); }
    private static void near(double actual, double expected, double relative, double absolute, String label) {
        assertions++;
        if (!Double.isFinite(actual) || !Double.isFinite(expected)
            || Math.abs(actual - expected) > absolute + relative * Math.abs(expected))
            throw new AssertionError(label + ": expected " + expected + ", actual " + actual);
    }
    private static void check(boolean value, String message) {
        assertions++;
        if (!value) throw new AssertionError(message);
    }
    private static void rejects(Runnable action) {
        assertions++;
        try { action.run(); } catch (IllegalArgumentException expected) { return; }
        throw new AssertionError("Expected invalid input to be rejected");
    }
    @FunctionalInterface private interface Checked { void run() throws Exception; }
    private static void rejectsChecked(Checked action) throws Exception {
        assertions++;
        try { action.run(); } catch (IllegalArgumentException expected) { return; }
        throw new AssertionError("Expected malformed CSV to be rejected");
    }
}
